-- MiniMax Week hackathon feature: per-artwork theme songs generated by
-- MiniMax Music 3.0 (lyrics reasoned by MiniMax M3). One song per
-- artwork + locale, reused across visitors to avoid regenerating the ~2min job.
--
-- The composition job is long (~1-2 min), so it cannot run inside a single
-- request on Cloudflare Workers. Instead the row tracks the job:
--   pending  - lyrics done, MiniMax Music job submitted (request_id set)
--   ready    - audio downloaded to R2, audio_url points at /api/theme-song/audio
--   failed   - lyric or music step failed; error holds the reason
-- The client polls GET /api/theme-song until the row leaves 'pending'.

CREATE TABLE IF NOT EXISTS artwork_theme_songs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL,
  locale TEXT NOT NULL DEFAULT 'ja',
  status TEXT NOT NULL DEFAULT 'pending',
  request_id TEXT NOT NULL DEFAULT '',
  audio_url TEXT NOT NULL DEFAULT '',
  lyrics TEXT NOT NULL DEFAULT '',
  style_prompt TEXT NOT NULL DEFAULT '',
  error TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (slug, locale)
);

CREATE INDEX IF NOT EXISTS artwork_theme_songs_slug_idx ON artwork_theme_songs (slug, locale);
